#include <cctype>
#include <iostream>
#include <string>

std::string titleCase(std::string text) {
    for (std::size_t i = 0; i < text.size(); i++) {
        if (i == 0 || text[i - 1] == ' ') {
            text[i] = std::toupper(static_cast<unsigned char>(text[i]));
        }
    }
    return text;
}

int main() {
    std::string text;
    std::getline(std::cin, text);
    std::cout << titleCase(text) << "\n";
    return 0;
}

